package com.prelina.findmynet

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Fixed-vector tests for [SrpClient].
 *
 * The vectors were generated by an independent Python reference
 * implementation (~/workspace/findmy-mac/srp-vectors/srp_reference.py)
 * and cross-checked there against the real pysrp library driven the
 * way iCloud3 drives it (rfc5054_enable + no_username_in_x, SHA-256,
 * NG_2048). If the Kotlin maths drifts from pysrp in any byte or
 * padding convention, these tests fail.
 */
class SrpClientTest {

    private data class Vector(
        val protocol: String,
        val derivedKeyHex: String,
        val expectedM1Hex: String,
        val expectedM2Hex: String,
        val expectedKHex: String
    )

    private val vectors = listOf(
        Vector(
            protocol = "s2k",
            derivedKeyHex = "4ff3fe32693c9d5ae86f330edcb2adff7a998328d7685115e70166c0fdbf465d",
            expectedM1Hex = "8ead8d6fbf7a672433fdecf45ad872a7a19375329120d2f65b8a70d5c37de4c5",
            expectedM2Hex = "64638284aa32b0da23e8336907ad71cb5b354346b5a78e2e6146576a013226ef",
            expectedKHex = "2a7c4a75fcc44b52ac24b526e3ac692c439cf691227de8ec23ad321f0b20dc58"
        ),
        Vector(
            protocol = "s2k_fo",
            derivedKeyHex = "0bf9e7b55e692901f572fe9ed9eb497897e6e18411af7715c36aec2d028b75be",
            expectedM1Hex = "985f9857e82cfa9c6381d2a10317e10ec76d60492a5884cf358301a91e9066f8",
            expectedM2Hex = "8e7d453996fa0866e6884bc6edbdc122c7c6050d1c7b98f004aa0a52431cf511",
            expectedKHex = "1b61130396a1370308afb4474f27f4e825d5ad208ab85032996517620ad70e1a"
        )
    )

    @Test
    fun publicAMatchesVector() {
        val client = SrpClient(USERNAME, PASSWORD, hex(A_HEX))
        assertArrayEquals(hex(EXPECTED_A_HEX), client.publicA)
    }

    @Test
    fun derivePasswordKeyMatchesVectors() {
        for (v in vectors) {
            val derived = SrpClient.derivePasswordKey(PASSWORD, hex(SALT_HEX), ITERATIONS, v.protocol)
            assertArrayEquals("protocol ${v.protocol}", hex(v.derivedKeyHex), derived)
        }
    }

    @Test
    fun processChallengeMatchesVectors() {
        for (v in vectors) {
            val client = SrpClient(USERNAME, PASSWORD, hex(A_HEX))
            val ok = client.processChallenge(hex(SALT_HEX), hex(B_HEX), ITERATIONS, v.protocol)
            assertTrue("processChallenge failed for ${v.protocol}", ok)
            assertArrayEquals("m1 (${v.protocol})", hex(v.expectedM1Hex), client.clientProofM1)
            assertArrayEquals("m2 (${v.protocol})", hex(v.expectedM2Hex), client.expectedServerProofM2)
            assertArrayEquals("K (${v.protocol})", hex(v.expectedKHex), client.srpSessionKey)
        }
    }

    @Test
    fun verifyServerProofAcceptsExpectedAndRejectsOthers() {
        val v = vectors[0]
        val client = SrpClient(USERNAME, PASSWORD, hex(A_HEX))
        assertTrue(client.processChallenge(hex(SALT_HEX), hex(B_HEX), ITERATIONS, v.protocol))
        assertTrue(client.verifyServerProof(hex(v.expectedM2Hex)))
        // The other protocol's proof must not verify for this session.
        assertFalse(client.verifyServerProof(hex(vectors[1].expectedM2Hex)))
        // m1 is not the server proof (the deleted icloud3 code conflated them).
        assertFalse(client.verifyServerProof(hex(v.expectedM1Hex)))
    }

    @Test
    fun unsupportedProtocolIsRejected() {
        val client = SrpClient(USERNAME, PASSWORD, hex(A_HEX))
        assertFalse(client.processChallenge(hex(SALT_HEX), hex(B_HEX), ITERATIONS, "s3k"))
        assertEquals(null, SrpClient.derivePasswordKey(PASSWORD, hex(SALT_HEX), ITERATIONS, "s3k"))
    }

    private fun hex(s: String): ByteArray {
        require(s.length % 2 == 0)
        return ByteArray(s.length / 2) { i ->
            s.substring(i * 2, i * 2 + 2).toInt(16).toByte()
        }
    }

    private companion object {
        const val USERNAME = "srp.vector@example.com"
        const val PASSWORD = "Vector-Password!42"
        const val ITERATIONS = 20066
        const val SALT_HEX = "5b8f3e2a91c04d77a6e15f20983bcd4e"
        const val A_HEX =
            ""
        const val B_HEX =
            ""
        const val EXPECTED_A_HEX =
            ""
    }
}
